SQL="BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;\nDO $$ BEGIN\nIF EXISTS (SELECT 1 FROM generic_task b WHERE b.status IN ('pending','processing') AND EXISTS (SELECT 1 FROM generic_task s WHERE s.parent_task_id=b.id AND s.task_type='promo_link.claim.v1')) OR EXISTS (SELECT 1 FROM generic_task WHERE task_type='promo_link.claim.v1' AND status IN ('pending','processing')) OR EXISTS (SELECT 1 FROM side_effect_intent WHERE status IN ('prepared','claim_retry_blocked')) OR EXISTS (SELECT 1 FROM generic_task_item WHERE status='processing') OR EXISTS (SELECT 1 FROM channel_sync_task_item WHERE status='processing') THEN RAISE EXCEPTION 'PUBLIC_CUTOVER_PAUSE_GATE=FAIL'; END IF;\nIF EXISTS (SELECT 1 FROM generic_task WHERE (task_type LIKE 'article.publish.%' OR task_type LIKE 'article.generate.%') AND status IN ('pending','processing')) THEN RAISE EXCEPTION 'ARTICLE_INFLIGHT=FAIL'; END IF;\nEND $$;\nSELECT 'PUBLIC_CUTOVER_PAUSE_GATE=PASS';\nSELECT json_build_object('read_at',clock_timestamp(),'article_publish_inflight',(SELECT count(*) FROM generic_task WHERE task_type LIKE 'article.publish.%' AND status IN ('pending','processing')),'article_generate_inflight',(SELECT count(*) FROM generic_task WHERE task_type LIKE 'article.generate.%' AND status IN ('pending','processing')),'new_column_exists',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='canonical_tag' AND column_name='is_homepage_visible'),'canonical_tags',(SELECT count(*) FROM canonical_tag),'migrations',(SELECT json_agg(json_build_object('name',migration_name,'checksum',checksum,'finished',finished_at IS NOT NULL,'rolled_back',rolled_back_at IS NOT NULL) ORDER BY migration_name) FROM _prisma_migrations),'outbox_urls_by_status',(SELECT json_object_agg(status,n) FROM (SELECT status,count(*) n FROM indexnow_outbox GROUP BY status) x),'delivery_taskItems_by_status',(SELECT json_object_agg(status,n) FROM (SELECT i.status,count(*) n FROM generic_task_item i JOIN generic_task t ON t.id=i.task_id WHERE t.task_type='indexnow_delivery' GROUP BY i.status) x),'delivery_tasks_by_status',(SELECT json_object_agg(status,n) FROM (SELECT status,count(*) n FROM generic_task WHERE task_type='indexnow_delivery' GROUP BY status) x),'sweeps_last_10_minutes',(SELECT count(*) FROM schedule_run WHERE schedule_key='indexnow.sweep' AND scheduled_for>=now()-interval '10 minutes'),'sweep_schedule_latest',(SELECT json_agg(json_build_object('scheduled_for',scheduled_for,'status',status) ORDER BY scheduled_for) FROM (SELECT scheduled_for,status FROM schedule_run WHERE schedule_key='indexnow.sweep' ORDER BY scheduled_for DESC LIMIT 10) x),'search_values',(SELECT json_agg(site_search_enabled) FROM site_setting));\nCOMMIT;\n"
